		) AS TO_bettrans
	CROSS APPLY (
			SELECT SUM(h.PayoutAdjust) AS sum_payout
			FROM CustLimitBetHistory_789 h WITH (NOLOCK)
				INNER JOIN bettrans b WITH (NOLOCK) ON b.TransId = h.Transid AND b.statusID NOT IN (101)
			WHERE h.CustID = l.CustID
				AND h.Matchid = l.Matchid
		) AS PO_History
WHERE EventTypeID = 4
	AND matchid = 29 
	AND l.AccumTurnover <> TO_bettrans.sum_stake
							
--LIC
UPDATE l SET l.AccumTurnover = TO_bettrans.sum_stake, l.AccumPayout = PO_History.sum_payout					
FROM CustLimitBet_LIC l WITH (ROWLOCK, UPDLOCK)		
	INNER JOIN @tmpCustId t ON t.CustId = l.CustID
	CROSS APPLY (						
			SELECT ISNULL(SUM(stake),0) AS sum_stake 
			FROM bettrans b WITH (NOLOCK)	
			WHERE matchid IN (9,29) 
				AND b.custid = l.custid 
				AND bettype IN (9,29) 
				AND ruben = 0				
				AND oddsid = 1 --soccer				
		) AS TO_bettrans
	CROSS APPLY (
			SELECT SUM(h.PayoutAdjust) AS sum_payout
			FROM CustLimitBetHistory_LIC h WITH (NOLOCK)
				INNER JOIN bettrans b WITH (NOLOCK) ON b.TransId = h.Transid AND b.statusID NOT IN (101)
			WHERE h.CustID = l.CustID
				AND h.Matchid = l.Matchid
		) AS PO_History
WHERE EventTypeID = 3 
	AND matchid = 29 
	AND l.AccumTurnover <> TO_bettrans.sum_stake	

UPDATE l SET l.AccumTurnover = TO_bettrans.sum_stake, l.AccumPayout = PO_History.sum_payout					
FROM CustLimitBet_LIC l WITH (ROWLOCK, UPDLOCK)		
	INNER JOIN @tmpCustId t ON t.CustId = l.CustID
	CROSS APPLY (						
			SELECT  ISNULL(SUM(stake),0) AS sum_stake 
			FROM bettrans WITH (NOLOCK)					
			WHERE matchid in (9,29) 
				AND custid = l.custid 
				AND bettype IN (9,29) 
				AND ruben = 0					
				AND oddsid = 99 --mix sports			
		) AS TO_bettrans
	CROSS APPLY (
			SELECT SUM(h.PayoutAdjust) AS sum_payout
			FROM CustLimitBetHistory_LIC h WITH (NOLOCK)
				INNER JOIN bettrans b WITH (NOLOCK) ON b.TransId = h.Transid AND b.statusID NOT IN (101)
			WHERE h.CustID = l.CustID
				AND h.Matchid = l.Matchid
		) AS PO_History
WHERE EventTypeID = 4
	AND matchid = 29 
	AND l.AccumTurnover <> TO_bettrans.sum_stake						
